+function colorFor(text) {
+  const colors = ['#5f5adc', '#df654e', '#1d6fcc', '#d59424', '#208566'];
+  return colors[text.split('').reduce((n, c) => n + c.charCodeAt(0), 0) % colors.length];
+}
