@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;600;700&display=swap');

:root { font-family: 'DM Sans', sans-serif; color: #24231f; background: #f8f8f5; font-synthesis: none; --ink: #24231f; --muted: #797870; --line: #e8e7e1; --paper: #fff; --purple: #6157d8; }
* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; min-height: 100vh; background: #f8f8f5; }
button, input, textarea, select { font: inherit; }
button { cursor: pointer; }
.app-shell { min-height: 100vh; display: flex; }
.sidebar { width: 248px; flex: 0 0 248px; min-height: 100vh; background: #f2f1ed; border-right: 1px solid #e2e1dc; padding: 29px 18px 18px; display: flex; flex-direction: column; position: fixed; inset: 0 auto 0 0; z-index: 30; }
.brand { height: 44px; display: flex; align-items: center; gap: 10px; padding: 0 10px; margin-bottom: 27px; font: 700 21px 'Manrope', sans-serif; letter-spacing: -.5px; }
.brand-mark { width: 31px; height: 31px; border-radius: 9px; display: grid; place-items: center; color: white; background: #6358d9; transform: rotate(-3deg); box-shadow: 0 4px 12px rgba(97,87,216,.2); }
.nav-label { font-size: 10px; font-weight: 700; letter-spacing: 1.25px; color: #9a9991; margin: 0 10px 9px; }
.nav-item { border: 0; color: #6e6d66; background: transparent; border-radius: 9px; width: 100%; height: 42px; display: flex; align-items: center; gap: 11px; padding: 0 11px; margin: 2px 0; text-align: left; font-size: 14px; font-weight: 500; transition: .16s ease; }
.nav-item:hover { background: rgba(255,255,255,.66); color: var(--ink); }
.nav-item.active { color: #4f46bf; background: #e8e6f6; font-weight: 600; }
.nav-item em { margin-left: auto; color: #aaa9a1; font-size: 12px; font-style: normal; font-weight: 500; }
.nav-section { margin-top: 27px; }
.nav-label-row { display: flex; align-items: center; justify-content: space-between; padding-right: 8px; }
.nav-label-row button { border: 0; background: none; color: #99978e; padding: 2px; }
.tag-dot { width: 8px; height: 8px; border-radius: 50%; margin: 0 5px; }
.tag-dot.coral { background:#e87966; }.tag-dot.blue{background:#548fd5}.tag-dot.violet{background:#8b78d7}.tag-dot.amber{background:#dba53f}
.sidebar-bottom { margin-top: auto; }
.upgrade-card { background: #e9e7f5; border: 1px solid #dedbef; color: #5e55ca; padding: 13px; margin: 0 1px 15px; border-radius: 11px; display: flex; gap: 10px; }
.upgrade-card svg { flex: 0 0 auto; margin-top: 1px; }
.upgrade-card strong { color: #383445; font-size: 12px; display:block; margin-bottom: 3px; }
.upgrade-card p { margin: 0; color: #7d7989; font-size: 10px; line-height: 1.4; }
.profile { border-top: 1px solid #dfded8; display: flex; align-items:center; gap: 9px; padding: 17px 5px 2px; margin-top: 8px; }
.profile-avatar, .avatar { background: #df745c; color: white; border: 0; border-radius: 50%; display: grid; place-items: center; font-size: 11px; font-weight: 700; }
.profile-avatar { width: 32px; height: 32px; }.profile>div:nth-child(2){min-width:0; flex:1}.profile strong { display:block; font-size:11px; }.profile span { color:#99978e;font-size:9px;display:block;margin-top:2px}.profile svg{color:#96958e}
.main { margin-left: 248px; width: calc(100% - 248px); min-height: 100vh; }
.topbar { height: 78px; background: rgba(255,255,255,.82); backdrop-filter: blur(12px); border-bottom: 1px solid var(--line); display: flex; align-items:center; padding: 0 42px; position: sticky; top: 0; z-index: 20; }
.search-wrap { width: 420px; height: 40px; display:flex; align-items:center; gap: 10px; color:#9d9c94; }
.search-wrap input { flex:1; border:0; outline:0; background:transparent; color:var(--ink); font-size:14px; }
.search-wrap input::placeholder{color:#aaa9a3}.search-wrap kbd{font-family:inherit;font-size:10px;color:#9c9a92;background:#f2f1ed;border:1px solid #e1e0da;border-radius:5px;padding:3px 6px;box-shadow:0 1px 0 white}.search-wrap button{border:0;background:none;color:#999;display:grid;place-items:center}
.avatar { width: 35px; height:35px; margin-left:auto; box-shadow:0 0 0 3px white,0 0 0 4px #e4e2dc; }
.mobile-menu { display:none!important; margin-right:10px; }
.content { padding: 52px 4.5vw 70px; max-width: 1500px; margin: 0 auto; }
.title-row { display:flex; justify-content:space-between; align-items:flex-end; gap:20px; margin-bottom:39px; }
.eyebrow { color:#6157d8; font-size:10px; letter-spacing:1.5px; font-weight:700; margin:0 0 9px; }
